4	// Don't retry requests that failed due to authentication errors.
5	// The auth interceptor in connect.ts already handles token refresh and request retry.
6	// If the interceptor still throws Unauthenticated, the session is truly gone and the
7	// user will be redirected to /auth. A React Query retry would only fire a second
8	// failed refresh attempt and a second redirect call while navigation is already in progress.
9	const shouldRetry = (failureCount: number, error: unknown): boolean => {
10	  if (error instanceof ConnectError && error.code === Code.Unauthenticated) return false;
11	  return failureCount < 1;
12	};
13	
14	export const queryClient = new QueryClient({
15	  defaultOptions: {
16	    queries: {
17	      // Balanced approach: Fresh enough for collaboration, but reduces unnecessary refetches
18	      // Individual queries can override with shorter staleTime if needed (e.g., notifications)
19	      staleTime: 1000 * 30, // 30 seconds (increased from 10s for better performance)
20	      gcTime: 1000 * 60 * 5, // 5 minutes (formerly cacheTime)
21	      retry: shouldRetry,
22	      refetchOnWindowFocus: true, // Refetch when user returns to tab
23	      refetchOnReconnect: true, // Refetch when network reconnects
24	    },
25	    mutations: {
26	      retry: shouldRetry,
27	    },
28	  },
29	});
