3	/** Query parameter used to preserve the intended destination across the auth flow. */
4	export const AUTH_REDIRECT_PARAM = "redirect";
5	
6	/** Query parameter used to surface why the user was sent to the auth page. */
7	export const AUTH_REASON_PARAM = "reason";
8	
9	/** Reason code signalling that the user hit a memo that requires authentication. */
10	export const AUTH_REASON_PROTECTED_MEMO = "protected-memo";
11	
12	/**
13	 * Validates a post-authentication redirect target.
14	 *
15	 * Returns the path when it is a safe same-origin internal destination, otherwise `undefined`.
16	 * Rejected targets include: non-string / empty, protocol-relative URLs (`//host`), absolute URLs,
17	 * and any auth-family route (`/auth`, `/auth/callback`, …) which must not be a landing target
18	 * after sign-in.
19	 */
20	export function getSafeRedirectPath(path: string | null | undefined): string | undefined {
21	  if (!path) {
22	    return undefined;
23	  }
24	
25	  if (!path.startsWith("/") || path.startsWith("//")) {
26	    return undefined;
27	  }
28	
29	  // Never let a redirect target point back into the auth flow — it would either
30	  // bounce the user in a guest/auth guard loop or hijack the OAuth callback.
31	  if (path === ROUTES.AUTH || path.startsWith(`${ROUTES.AUTH}/`) || path.startsWith(`${ROUTES.AUTH}?`)) {
32	    return undefined;
33	  }
34	
35	  return path;
36	}
37	
38	/**
39	 * Builds a URL pointing at the auth entry page, optionally embedding a validated
40	 * `redirect` target and a machine-readable `reason` code.
41	 */
42	export function buildAuthRoute(options?: { redirect?: string | null; reason?: string | null }): string {
43	  const searchParams = new URLSearchParams();
44	  const redirectPath = getSafeRedirectPath(options?.redirect);
45	
46	  if (redirectPath) {
47	    searchParams.set(AUTH_REDIRECT_PARAM, redirectPath);
48	  }
49	
50	  if (options?.reason) {
51	    searchParams.set(AUTH_REASON_PARAM, options.reason);
52	  }
53	
54	  const search = searchParams.toString();
55	  return search ? `${ROUTES.AUTH}?${search}` : ROUTES.AUTH;
56	}
