58	const PUBLIC_ROUTE_PREFIXES = [
59	  ROUTES.AUTH, // Authentication pages
60	  ROUTES.ABOUT, // About page
61	  ROUTES.EXPLORE, // Explore page
62	  `${ROUTES.SHARED_MEMO}/`, // Shared memo pages (share-link viewer)
63	  "/u/", // User profile pages (dynamic)
64	  "/memos/", // Individual memo detail pages (dynamic)
65	] as const;
