67	/**
68	 * Reports whether a given pathname corresponds to a page that unauthenticated
69	 * visitors are allowed to view without being bounced to the auth page.
70	 */
71	export function isPublicRoute(path: string): boolean {
72	  return PUBLIC_ROUTE_PREFIXES.some((route) => path.startsWith(route));
73	}
