91	/**
92	 * Appends the given search params to a path, so links between auth pages
93	 * (sign-in <-> sign-up) preserve the redirect target and other params.
94	 */
95	export function appendSearchParams(path: string, searchParams: URLSearchParams): string {
96	  const queryString = searchParams.toString();
97	  return queryString ? `${path}?${queryString}` : path;
